<script setup lang="ts">
import { computed, ref } from "vue"; import { useQuery } from "@tanstack/vue-query"; import { api } from "@/api/http"; import type { MaterialSummary } from "@/api/types";
const search=ref("");const type=ref("");const selected=ref<number|null>(null);const detailTab=ref("overview");
const list=useQuery({queryKey:["materials"],queryFn:()=>api<MaterialSummary[]>("/api/materials")});
const detail=useQuery({queryKey:computed(()=>["material",selected.value]),queryFn:()=>api<any>(`/api/materials/${selected.value}`),enabled:computed(()=>selected.value!==null)});
const types=computed(()=>[...new Set((list.data.value||[]).map(x=>x.file_type).filter(Boolean))]);const filtered=computed(()=>(list.data.value||[]).filter(x=>(!search.value||x.filename.toLowerCase().includes(search.value.toLowerCase()))&&(!type.value||x.file_type===type.value)));
</script>
<template><div class="page-stack materials-page"><header class="page-header"><div><h1>材料库</h1><p>材料可被多个任务复用；任务关系在材料详情中保留。</p></div></header><section class="surface material-shell"><div class="material-list"><div class="filters"><input v-model="search" placeholder="搜索文件名"/><select v-model="type"><option value="">全部类型</option><option v-for="item in types" :key="item">{{ item }}</option></select></div><div class="table-head"><span>文件名</span><span>类型</span><span>内容单元</span><span>关联任务</span></div><button v-for="item in filtered" :key="item.id" class="file-row" :class="{selected:selected===item.id}" @click="selected=item.id"><span><b>{{ item.filename }}</b><small v-if="item.is_duplicate">重复材料 · 来源 #{{ item.duplicate_of }}</small></span><span>{{ item.file_type || '—' }}</span><span>{{ item.unit_count }}</span><span>{{ item.tasks?.length || 0 }}</span></button><div v-if="!filtered.length" class="empty"><div><strong>暂无材料</strong>材料会在创建任务时进入材料库。</div></div></div><aside class="material-detail" :class="{open:selected!==null}"><template v-if="detail.data.value"><div class="detail-head"><div><small>材料详情</small><h2>{{ detail.data.value.filename }}</h2></div><button class="btn tertiary" @click="selected=null">关闭</button></div><div class="tabs"><button v-for="tab in [['overview','概览'],['content','解析内容'],['meta','元数据']]" :key="tab[0]" class="tab" :class="{active:detailTab===tab[0]}" @click="detailTab=tab[0]">{{ tab[1] }}</button></div><div v-if="detailTab==='overview'" class="detail-body"><dl><dt>文件类型</dt><dd>{{ detail.data.value.file_type }}</dd><dt>内容单元</dt><dd>{{ detail.data.value.units?.length || 0 }}</dd><dt>关联任务</dt><dd>{{ detail.data.value.tasks?.length || 0 }}</dd></dl><h3>使用记录</h3><RouterLink v-for="task in detail.data.value.tasks || []" :key="task.task_id || task" :to="`/tasks/${task.task_id || task}`" class="task-use">{{ task.theme || task.task_id || task }}</RouterLink></div><div v-else-if="detailTab==='content'" class="unit-list"><details v-for="unit in detail.data.value.units || []" :key="unit.id"><summary><span>{{ unit.kind }}</span><b>{{ unit.page ? `第 ${unit.page} 页` : `单元 ${unit.id}` }}</b></summary><p>{{ unit.content || unit.image_desc || '无文本内容' }}</p></details></div><pre v-else class="metadata">{{ JSON.stringify(detail.data.value.units?.[0]?.metadata || {}, null, 2) }}</pre></template><div v-else class="empty"><div><strong>选择一份材料</strong>查看解析内容、元数据和任务关系。</div></div></aside></section></div></template>
<style scoped>.material-shell{display:grid;grid-template-columns:minmax(0,1fr) 390px;min-height:620px;overflow:hidden}.material-list{min-width:0;border-right:1px solid var(--color-border)}.filters{display:grid;grid-template-columns:1fr 150px;gap:12px;padding:16px}.table-head,.file-row{display:grid;grid-template-columns:minmax(230px,1fr) 80px 90px 80px;gap:12px;align-items:center}.table-head{padding:8px 16px;color:var(--color-faint);background:var(--color-surface-soft);border-block:1px solid var(--color-border);font-size:12px}.file-row{width:100%;padding:12px 16px;text-align:left;border:0;border-bottom:1px solid var(--color-border);background:#fff}.file-row:hover,.file-row.selected{background:#f4f7fb}.file-row b,.file-row small{display:block}.file-row small{color:var(--color-warning);font-size:11px}.material-detail{min-width:0;background:#fbfcfd}.detail-head{display:flex;justify-content:space-between;gap:12px;padding:20px 20px 10px}.detail-head small{color:var(--color-faint)}.detail-head h2{margin:3px 0;word-break:break-all}.material-detail .tabs{padding:0 20px}.detail-body,.unit-list,.metadata{padding:20px;margin:0}.detail-body dl{display:grid;grid-template-columns:90px 1fr;gap:9px;margin:0 0 24px}.detail-body dt{color:var(--color-muted)}.detail-body dd{margin:0}.task-use{display:block;padding:9px 0;border-top:1px solid var(--color-border);color:var(--color-primary)}.unit-list{display:grid;gap:8px;max-height:520px;overflow:auto}.unit-list details{padding:10px;border:1px solid var(--color-border);background:#fff}.unit-list summary{display:flex;justify-content:space-between;cursor:pointer}.unit-list summary span{color:var(--color-primary)}.unit-list summary b{font-size:12px}.unit-list p{white-space:pre-wrap}.metadata{white-space:pre-wrap;overflow:auto;font-size:12px}@media(max-width:1000px){.material-shell{grid-template-columns:1fr}.material-detail{position:fixed;inset:60px 0 0 auto;z-index:22;width:min(440px,100%);box-shadow:var(--shadow-float);transform:translateX(100%);transition:transform var(--motion-fast)}.material-detail.open{transform:none}}@media(max-width:650px){.table-head,.file-row{grid-template-columns:1fr 60px}.table-head>*:nth-child(3),.table-head>*:nth-child(4),.file-row>*:nth-child(3),.file-row>*:nth-child(4){display:none}.filters{grid-template-columns:1fr}}</style>
